function validate([palindrome]) {
  if (typeof palindrome !== 'string' || palindrome.length < 1 || palindrome.length > 1000) return 'palindrome needs 1 to 1000 characters.';
  if (!/^[a-z]+$/.test(palindrome)) return 'palindrome uses only lowercase English letters.';
  for (let i = 0, j = palindrome.length - 1; i < j; i++, j--) {
    if (palindrome[i] !== palindrome[j]) return 'palindrome must read the same in both directions.';
  }
  return null;
}

