function breakPalindrome(palindrome) {
  const isPalindrome = s => s === [...s].reverse().join('');
  let best = null;
  for (let pos = 0; pos < palindrome.length; pos++) {
    for (let code = 97; code <= 122; code++) {
      const letter = String.fromCharCode(code);
      if (letter === palindrome[pos]) continue;
      const candidate = palindrome.slice(0, pos) + letter + palindrome.slice(pos + 1);
      if (isPalindrome(candidate)) continue;
      if (best === null || candidate < best) best = candidate;
    }
  }
  return best === null ? '' : best;
}

