function generate(rand, size) {
  const n = size === 'large' ? 900 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 9);
  const style = rand();
  const letter = () => {
    if (style < 0.25) return 'a';
    if (style < 0.6) return rand() < 0.85 ? 'a' : 'b';
    return String.fromCharCode(97 + Math.floor(rand() * 26));
  };
  const half = Array.from({ length: Math.floor(n / 2) }, letter);
  const middle = n % 2 === 1 ? [String.fromCharCode(97 + Math.floor(rand() * 26))] : [];
  return [[...half, ...middle, ...half.slice().reverse()].join('')];
}
